INSERT INTO t_p90536134_security_requirement.technologies
  (id, name, status, description, versions, tech_domain_ids, tags, attachments)
VALUES
  ('tech.001', 'JWT (JSON Web Token)',         'Активен',      'Стандарт открытого формата токенов доступа на основе JSON. Используется для передачи утверждений между сторонами в виде подписанного объекта, обеспечивая аутентификацию и авторизацию без сохранения состояния на сервере.',
   ARRAY['RFC 7519','9.0'],    ARRAY['tech.dom.007','tech.dom.001'], ARRAY['authn','token','stateless','oauth'],     '[]'),

  ('tech.002', 'OAuth 2.0',                    'Активен',      'Протокол авторизации, позволяющий сторонним приложениям получать ограниченный доступ к ресурсам пользователя без раскрытия учётных данных. Используется для делегированного доступа через access/refresh-токены.',
   ARRAY['RFC 6749','2.1 draft'], ARRAY['tech.dom.007','tech.dom.001'], ARRAY['authz','protocol','delegation','token'],  '[]'),

  ('tech.003', 'OpenID Connect (OIDC)',         'Активен',      'Уровень идентификации поверх OAuth 2.0. Предоставляет стандартный способ проверки личности конечного пользователя через ID-токен (JWT), выданный провайдером идентификации.',
   ARRAY['1.0','Core 1.0'],    ARRAY['tech.dom.007','tech.dom.001'], ARRAY['authn','oidc','sso','federation'],       '[]'),

  ('tech.004', 'RBAC (Role-Based Access Control)','Активен',   'Модель управления доступом, где права назначаются пользователям через роли. Позволяет централизованно управлять разрешениями, снижая сложность администрирования и риск избыточных привилегий.',
   ARRAY['1.0'],               ARRAY['tech.dom.001','tech.dom.007'], ARRAY['access','authorization','model','rbac'], '[]'),

  ('tech.005', 'ABAC (Attribute-Based Access Control)','В разработке','Модель управления доступом на основе атрибутов субъекта, ресурса и среды. Обеспечивает гибкую политику доступа через XACML-правила, подходит для сложных контекстно-зависимых сценариев.',
   ARRAY['XACML 3.0'],         ARRAY['tech.dom.001'],               ARRAY['access','policy','attribute','xacml'],  '[]'),

  ('tech.006', 'TLS/SSL (Transport Layer Security)','Активен', 'Криптографический протокол, обеспечивающий шифрование данных при передаче между клиентом и сервером. TLS 1.3 является актуальной версией. Защищает от атак перехвата и подмены данных.',
   ARRAY['TLS 1.2','TLS 1.3'], ARRAY['tech.dom.018','tech.dom.006'], ARRAY['encryption','tls','ssl','transport'],   '[]'),

  ('tech.007', 'AES (Advanced Encryption Standard)','Активен', 'Симметричный алгоритм блочного шифрования. AES-256 является стандартом де-факто для защиты данных в покое. Применяется для шифрования БД, дисков, файлов и резервных копий.',
   ARRAY['AES-128','AES-192','AES-256'], ARRAY['tech.dom.018','tech.dom.010'], ARRAY['encryption','symmetric','aes','at-rest'], '[]'),

  ('tech.008', 'RSA',                           'Активен',      'Асимметричный криптографический алгоритм. Используется для шифрования ключей, цифровой подписи и обмена ключами. Рекомендуемый размер ключа — 2048 бит и выше.',
   ARRAY['PKCS#1','2048-bit','4096-bit'], ARRAY['tech.dom.018'],            ARRAY['encryption','asymmetric','pki','signature'],'[]'),

  ('tech.009', 'MFA / 2FA',                     'Активен',      'Многофакторная аутентификация — требование предоставить два или более независимых фактора для подтверждения личности. Критически снижает риск компрометации при утечке паролей.',
   ARRAY['TOTP RFC 6238','FIDO2'], ARRAY['tech.dom.007','tech.dom.001'],  ARRAY['authn','mfa','totp','fido2'],           '[]'),

  ('tech.010', 'SIEM',                          'Активен',      'Система управления событиями безопасности и информацией. Агрегирует, коррелирует и анализирует логи из различных источников в реальном времени для обнаружения угроз и расследования инцидентов.',
   ARRAY['1.0'],               ARRAY['tech.dom.003','tech.dom.008'],  ARRAY['monitoring','logging','soc','detection'],  '[]'),

  ('tech.011', 'WAF (Web Application Firewall)', 'Активен',     'Межсетевой экран для веб-приложений. Анализирует HTTP-трафик и блокирует атаки класса OWASP Top 10: SQL-инъекции, XSS, CSRF, обход каталогов и другие веб-угрозы.',
   ARRAY['1.0'],               ARRAY['tech.dom.018','tech.dom.019'],  ARRAY['network','waf','firewall','owasp'],        '[]'),

  ('tech.012', 'Контейнеризация (Docker)',       'Активен',      'Технология упаковки приложения со всеми зависимостями в изолированный контейнер. С точки зрения ИБ — изоляция процессов, неизменяемость образов, принцип минимальных привилегий.',
   ARRAY['20.10','24.0','25.0'], ARRAY['tech.dom.005','tech.dom.019'], ARRAY['container','docker','isolation','immutable'],'[]'),

  ('tech.013', 'Kubernetes (K8s)',              'Активен',      'Оркестратор контейнеров с встроенными механизмами безопасности: RBAC, Pod Security Standards, Network Policies, Secrets management. Обеспечивает безопасное развёртывание и масштабирование сервисов.',
   ARRAY['1.28','1.29','1.30'], ARRAY['tech.dom.005','tech.dom.001'], ARRAY['k8s','orchestration','container','rbac'],  '[]'),

  ('tech.014', 'HashiCorp Vault',               'Активен',      'Централизованное хранилище секретов и управление PKI. Обеспечивает динамическое управление учётными данными, шифрование как услугу и ротацию секретов без изменения кода приложений.',
   ARRAY['1.14','1.15'],       ARRAY['tech.dom.001','tech.dom.007'],  ARRAY['secrets','vault','pki','dynamic-creds'],  '[]'),

  ('tech.015', 'Балансировщик нагрузки',        'Активен',      'Распределение входящего трафика между несколькими серверами. С точки зрения ИБ — устранение SPOF, защита от DDoS, SSL-терминация, централизованное применение политик доступа.',
   ARRAY['L4','L7'],           ARRAY['tech.dom.018','tech.dom.006'],  ARRAY['network','ha','ddos','traffic'],          '[]'),

  ('tech.016', 'PKI (Public Key Infrastructure)','Активен',     'Инфраструктура открытых ключей для управления цифровыми сертификатами. Включает удостоверяющие центры, политики выдачи сертификатов, списки отзыва (CRL/OCSP). Основа TLS и цифровых подписей.',
   ARRAY['X.509 v3'],          ARRAY['tech.dom.018','tech.dom.007'],  ARRAY['pki','certificate','ca','x509'],          '[]'),

  ('tech.017', 'EDR (Endpoint Detection & Response)','Активен', 'Решение для мониторинга конечных точек, обнаружения и реагирования на угрозы. Собирает телеметрию с рабочих станций и серверов, анализирует поведение процессов и файловой системы.',
   ARRAY['1.0'],               ARRAY['tech.dom.019','tech.dom.008'],  ARRAY['edr','endpoint','detection','threat'],    '[]'),

  ('tech.018', 'Zero Trust Network Access (ZTNA)','В разработке','Архитектурная концепция: явная верификация каждого запроса независимо от сетевого расположения. Заменяет периметральную модель безопасности — «никогда не доверяй, всегда проверяй».',
   ARRAY['1.0'],               ARRAY['tech.dom.001','tech.dom.018'],  ARRAY['zero-trust','ztna','sase','identity'],    '[]'),

  ('tech.019', 'LDAP / Active Directory',       'Активен',      'Протокол и служба каталогов для централизованного управления учётными записями, группами и политиками. Основа корпоративной IAM-инфраструктуры в большинстве организаций.',
   ARRAY['v3','AD 2019','AD 2022'], ARRAY['tech.dom.007','tech.dom.001'],ARRAY['ldap','ad','directory','iam'],          '[]'),

  ('tech.020', 'SOAR',                          'В разработке', 'Платформа оркестрации, автоматизации и реагирования на инциденты безопасности. Автоматизирует рутинные задачи SOC: обогащение алертов, блокировку угроз, уведомления и формирование отчётов.',
   ARRAY['1.0'],               ARRAY['tech.dom.008','tech.dom.003'],  ARRAY['soar','automation','incident','soc'],     '[]'),

  ('tech.021', 'Honeypot / Deception',          'В разработке', 'Технология обмана атакующих через развёртывание ложных ресурсов (honeypot, honeytoken, honeycredential). Позволяет обнаружить внутренние угрозы и продвижение атакующего в сети.',
   ARRAY['1.0'],               ARRAY['tech.dom.019','tech.dom.003'],  ARRAY['deception','honeypot','threat-intel'],    '[]'),

  ('tech.022', 'DLP (Data Loss Prevention)',    'Активен',      'Системы предотвращения утечки данных. Контролируют каналы передачи информации (почта, USB, принтеры, веб) и блокируют несанкционированную передачу конфиденциальных данных.',
   ARRAY['1.0'],               ARRAY['tech.dom.010','tech.dom.018'],  ARRAY['dlp','data-loss','privacy','classification'],'[]'),

  ('tech.023', 'PAM (Privileged Access Management)','Активен',  'Управление привилегированным доступом: хранение, ротация и контроль использования паролей привилегированных учётных записей, запись сессий администраторов.',
   ARRAY['1.0'],               ARRAY['tech.dom.001','tech.dom.007'],  ARRAY['pam','privilege','admin','session'],      '[]'),

  ('tech.024', 'IDS/IPS',                       'Активен',      'Системы обнаружения и предотвращения вторжений. Анализируют сетевой трафик на сигнатуры атак и аномальное поведение, автоматически блокируя подозрительные соединения.',
   ARRAY['Snort 3','Suricata 7'], ARRAY['tech.dom.018','tech.dom.019'],ARRAY['ids','ips','network','intrusion'],        '[]'),

  ('tech.025', 'HSM (Hardware Security Module)', 'Активен',     'Аппаратный модуль безопасности для защищённого хранения криптографических ключей и выполнения операций шифрования. Обеспечивает физическую защиту ключей от извлечения.',
   ARRAY['FIPS 140-2','FIPS 140-3'], ARRAY['tech.dom.018','tech.dom.001'], ARRAY['hsm','hardware','key-management','fips'], '[]')
ON CONFLICT (id) DO NOTHING;
